add_task(function test_setErrorState() {
  customElement.setErrorState("error");

  Assert.equal(
    input.ariaInvalid,
    "true",
    "The input should have aria-invalid set as true"
  );

  const errorMessage = customElement.querySelector(`#${input.id}ErrorMessage`);

  Assert.deepEqual(
    input.ariaDescribedByElements,
    [errorMessage],
    "The input should have the error message element set for aria-describedby"
  );

  Assert.equal(
    errorMessage.role,
    "alert",
    "The error message should have the alert role set"
  );

  customElement.setErrorState("");

  Assert.equal(
    input.ariaInvalid,
    "false",
    "The input should have aria-invalid set as false"
  );

  Assert.deepEqual(
    input.ariaDescribedByElements,
    [],
    "The input should not have any elements set for aria-describedby"
  );

  Assert.ok(
    !errorMessage.role,
    "The error message should not have role attribute"
  );
});

add_task(function test_setErrorStateCanHideError() {
  customElement.setErrorState("error", { showError: false });

  Assert.equal(
    input.ariaInvalid,
    "false",
    "The input should not expose a hidden error as aria-invalid"
  );
  Assert.ok(!input.validity.valid, "The input should still be invalid");
  Assert.deepEqual(
    input.ariaDescribedByElements,
    [],
    "The hidden error should not describe the input"
  );
  Assert.ok(
    !customElement.querySelector(`#${input.id}ErrorMessage`).role,
    "The hidden error message should not have role attribute"
  );

  customElement.setErrorState("");
